                raise SQLSyntaxError("Expected ',' or ')' after column name")

            if tokens[i].value == ")":
                break

            if tokens[i].value != ",":
                raise SQLSyntaxError("Expected ',' after column name")

            i += 1

        if tokens[i].type != TokenType.OPERATOR or tokens[i].value != ")":
            raise SQLSyntaxError("Expected ')' to close column list")

        i += 1

    if i >= len(tokens) or tokens[i].value.upper() != "VALUES":
        raise SQLSyntaxError("Expected 'VALUES' keyword")

    i += 1

    if i >= len(tokens) or tokens[i].type != TokenType.OPERATOR or tokens[i].value != "(":
        raise SQLSyntaxError("Expected '(' after 'VALUES'")

    i += 1
    values = []
    while i < len(tokens):
        if tokens[i].type == TokenType.INTEGER:
            values.append(int(tokens[i].value))
