        stmt_tokens = tokens[:semicolon_index]

        if stmt_tokens:
            try:
                statements.append(parse(stmt_tokens))
            except SQLSyntaxError:
                raise SQLSyntaxError(f"Malformed statement: {' '.join(token.value for token in stmt_tokens)}")

        # Move past the found ';' or reach EOF
        tokens = tokens[semicolon_index + 1:]

    return statements


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    if not tokens or tokens[-1].type != TokenType.EOF:
        raise SQLSyntaxError("Unexpected tokens or missing EOF")

    # Skip the EOF token for parsing
    tokens = tokens[:-1]

    expr = _parse_or_expr(tokens)

    if tokens:
        raise SQLSyntaxError("Trailing tokens after expression")

    return expr


