            values.append(int(tokens[i].value))
        elif tokens[i].type == TokenType.STRING:
            values.append(tokens[i].value)
        elif tokens[i].value.upper() == "TRUE":
            values.append(True)
        elif tokens[i].value.upper() == "FALSE":
            values.append(False)
        elif tokens[i].value.upper() == "NULL":
